app_css:
.tool-app-loanscope { color: #172554; max-width: 900px; }
.tool-app-loanscope .ls-grid { display: grid; grid-template-columns: 1fr 1.4fr; gap: 16px; margin-bottom: 18px; }
.tool-app-loanscope .ls-panel { background: #eff6ff; border-radius: 14px; padding: 18px; }
.tool-app-loanscope .ls-h3 { margin: 0 0 12px; font-size: 16px; color: #1e3a8a; }
.tool-app-loanscope .ls-label { display: block; font-size: 12.5px; font-weight: 700; color: #1e40af; margin: 12px 0 5px; }
.tool-app-loanscope .ls-label:first-of-type { margin-top: 0; }
.tool-app-loanscope .ls-input { width: 100%; box-sizing: border-box; border: 1px solid #bfdbfe; border-radius: 10px; padding: 9px 11px; font-size: 14px; font-family: inherit; color: #172554; background: #fff; }
.tool-app-loanscope .ls-note { font-size: 12px; color: #3b82f6; margin: 14px 0 0; }
.tool-app-loanscope .ls-big { display: flex; align-items: baseline; gap: 10px; margin-bottom: 14px; }
.tool-app-loanscope .ls-big span:first-child { font-size: 36px; font-weight: 800; color: #1d4ed8; }
.tool-app-loanscope .ls-big-label { font-size: 13px; color: #3b82f6; }
.tool-app-loanscope .ls-kpis { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-bottom: 14px; }
.tool-app-loanscope .ls-kpi { background: #fff; border-radius: 10px; padding: 10px 12px; display: flex; flex-direction: column; gap: 4px; }
.tool-app-loanscope .ls-kpi-label { font-size: 11.5px; font-weight: 600; color: #3b82f6; }
.tool-app-loanscope .ls-kpi strong { font-size: 16px; color: #1e3a8a; }
.tool-app-loanscope .ls-bar-wrap { display: flex; align-items: center; gap: 10px; margin-bottom: 8px; }
.tool-app-loanscope .ls-bar-label { font-size: 12.5px; font-weight: 700; color: #1e40af; width: 64px; flex-shrink: 0; }
.tool-app-loanscope .ls-bar-track { flex: 1; height: 16px; background: #dbeafe; border-radius: 8px; overflow: hidden; }
.tool-app-loanscope .ls-bar { height: 100%; border-radius: 8px; }
.tool-app-loanscope .ls-bar-principal { background: #2563eb; }
.tool-app-loanscope .ls-bar-interest { background: #f59e0b; }
.tool-app-loanscope .ls-savings { font-size: 13.5px; color: #1e3a8a; background: #dbeafe; border-radius: 10px; padding: 10px 14px; margin: 12px 0 0; }
.tool-app-loanscope .ls-savings:empty { display: none; }
.tool-app-loanscope .ls-table-wrap { overflow-x: auto; background: #eff6ff; border-radius: 14px; padding: 18px; }
.tool-app-loanscope .ls-table { width: 100%; border-collapse: collapse; font-size: 13.5px; }
.tool-app-loanscope .ls-table th { text-align: left; font-size: 12px; text-transform: uppercase; letter-spacing: 0.04em; color: #3b82f6; padding: 6px 8px; border-bottom: 2px solid #bfdbfe; }
.tool-app-loanscope .ls-table td { padding: 7px 8px; border-bottom: 1px solid #dbeafe; color: #172554; }
.tool-app-loanscope .ls-table tr:last-child td { border-bottom: none; }
@media (max-width: 640px) { .tool-app-loanscope .ls-grid { grid-template-columns: 1fr; } .tool-app-loanscope .ls-kpis { grid-template-columns: 1fr 1fr; } }

app_js:
(function () {
  'use strict';
  function $(id) { return document.getElementById(id); }
  function money(n) {
    n = Math.round(n);
    return '$' + n.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  }
  function monthName(y, m) {
    var names = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    return names[m] + ' ' + y;
  }
  function num(id, fallback) {
    var v = parseFloat(($(id).value || '').toString().replace(/[^0-9.]/g, ''));
    return isNaN(v) ? fallback : v;
  }
  function schedule(P, monthlyRate, nMonths, basePayment, extra, startY, startM) {
    var bal = P, rows = [], totalInt = 0, monthsPaid = 0;
    var yPaid = 0, yInt = 0, curY = startY;
    while (bal > 0.005 && monthsPaid < nMonths + 600) {
      var interest = bal * monthlyRate;
      var pay = basePayment + extra;
      if (pay > bal + interest) pay = bal + interest;
      var principal = pay - interest;
      bal -= principal;
      totalInt += interest;
      monthsPaid++;
      yPaid += pay; yInt += interest;
      var yy = startY, mm = startM + monthsPaid - 1;
      yy += Math.floor(mm / 12); mm = mm % 12;
      if (monthsPaid % 12 === 0 || bal <= 0.005) {
        rows.push({ year: curY, paid: yPaid, interest: yInt, balance: Math.max(0, bal) });
        curY = yy + (mm === 11 ? 1 : 0);
        yPaid = 0; yInt = 0;
      }
    }
    return { rows: rows, totalInt: totalInt, monthsPaid: monthsPaid };
  }
  function calc() {
    var P = num('ls-amount', 250000);
    var apr = num('ls-rate', 6.5);
    var years = Math.max(1, Math.min(50, Math.round(num('ls-years', 30))));
    var extra = Math.max(0, num('ls-extra', 0));
    var startVal = $('ls-start').value || '2026-11';
    var parts = startVal.split('-');
    var startY = parseInt(parts[0], 10) || 2026;
    var startM = (parseInt(parts[1], 10) || 11) - 1;

    var r = apr / 100 / 12;
    var n = years * 12;
    var base = r > 0 ? P * r * Math.pow(1 + r, n) / (Math.pow(1 + r, n) - 1) : P / n;

    var withExtra = schedule(P, r, n, base, extra, startY, startM);
    var baseOnly = extra > 0 ? schedule(P, r, n, base, 0, startY, startM) : null;

    var totalPaid = P + withExtra.totalInt;
    var endY = startY, endM = startM + withExtra.monthsPaid - 1;
    endY += Math.floor(endM / 12); endM = endM % 12;

    $('ls-monthly').textContent = money(base + extra);
    $('ls-interest').textContent = money(withExtra.totalInt);
    $('ls-total').textContent = money(totalPaid);
    $('ls-payoff').textContent = monthName(endY, endM);
    var pr = totalPaid > 0 ? Math.round(P / totalPaid * 100) : 0;
    $('ls-barp').style.width = pr + '%';
    $('ls-bari').style.width = (100 - pr) + '%';

    var save = $('ls-savings');
    if (extra > 0 && baseOnly) {
      var saved = baseOnly.totalInt - withExtra.totalInt;
      var monthsSaved = baseOnly.monthsPaid - withExtra.monthsPaid;
      save.textContent = 'That ' + money(extra) + '/mo extra saves you ' + money(saved) +
        ' in interest and pays the loan off ' + monthsSaved + ' month' + (monthsSaved === 1 ? '' : 's') + ' early.';
    } else {
      save.textContent = '';
    }

    var tb = $('ls-tbody'), html = '';
    var rows = withExtra.rows;
    for (var i = 0; i < rows.length; i++) {
      html += '<tr><td>' + rows[i].year + '</td><td>' + money(rows[i].paid) + '</td><td>' +
        money(rows[i].interest) + '</td><td>' + money(rows[i].balance) + '</td></tr>';
    }
    tb.innerHTML = html;
  }
  var ids = ['ls-amount', 'ls-rate', 'ls-years', 'ls-start', 'ls-extra'];
  for (var i = 0; i < ids.length; i++) {
    $(ids[i]).addEventListener('input', calc);
  }
  calc();
})();
